     1→# ================================================================
     2→# Free IR 1.0 — Node 구조 정의
     3→# Free IR의 모든 노드를 FreeLang으로 표현
     4→# ================================================================
     5→
     6→# ----------------------------------------------------------------
     7→# 1. 타입 표현
     8→# ----------------------------------------------------------------
     9→
    10→fn ir_type_i8()   { return { "kind": "primitive", "name": "i8",   "size": 1 } }
    11→fn ir_type_i16()  { return { "kind": "primitive", "name": "i16",  "size": 2 } }
    12→fn ir_type_i32()  { return { "kind": "primitive", "name": "i32",  "size": 4 } }
    13→fn ir_type_i64()  { return { "kind": "primitive", "name": "i64",  "size": 8 } }
    14→fn ir_type_u8()   { return { "kind": "primitive", "name": "u8",   "size": 1 } }
    15→fn ir_type_u16()  { return { "kind": "primitive", "name": "u16",  "size": 2 } }
    16→fn ir_type_u32()  { return { "kind": "primitive", "name": "u32",  "size": 4 } }
    17→fn ir_type_u64()  { return { "kind": "primitive", "name": "u64",  "size": 8 } }
    18→fn ir_type_f32()  { return { "kind": "primitive", "name": "f32",  "size": 4 } }
    19→fn ir_type_f64()  { return { "kind": "primitive", "name": "f64",  "size": 8 } }
    20→fn ir_type_bool() { return { "kind": "primitive", "name": "bool", "size": 1 } }
    21→fn ir_type_void() { return { "kind": "primitive", "name": "void", "size": 0 } }
    22→
    23→fn ir_type_ptr(inner_type) {
    24→  return { "kind": "ptr", "inner": inner_type, "size": 8 }
    25→}
    26→
    27→fn ir_type_array(elem_type, count) {
    28→  size = elem_type["size"] * count
    29→  return { "kind": "array", "elem": elem_type, "count": count, "size": size }
    30→}
    31→
    32→fn ir_type_slice(elem_type) {
    33→  return { "kind": "slice", "elem": elem_type, "size": 16 }
    34→}
    35→
    36→fn ir_type_struct(name, fields) {
    37→  # fields = [{ "name": str, "type": IrType }, ...]
    38→  # size 계산 (alignment 포함, Phase 1: 단순 합산)
    39→  size = 0
    40→  i = 0
    41→  while i < len(fields) {
    42→    f = fields[i]
    43→    size = size + f["type"]["size"]
    44→    i = i + 1
    45→  }
    46→  return { "kind": "struct", "name": name, "fields": fields, "size": size }
    47→}
    48→
    49→fn ir_type_fn(param_types, ret_type) {
    50→  return { "kind": "fn", "params": param_types, "ret": ret_type, "size": 8 }
    51→}
    52→
    53→# ----------------------------------------------------------------
    54→# 2. 값(Value) 표현
    55→# ----------------------------------------------------------------
    56→
    57→# SSA 값: %name
    58→fn ir_val_reg(name, ty) {
    59→  return { "kind": "reg", "name": name, "type": ty }
    60→}
    61→
    62→# 정수 상수
    63→fn ir_val_int(value, ty) {
    64→  return { "kind": "const_int", "value": value, "type": ty }
    65→}
    66→
    67→# 부동소수 상수
    68→fn ir_val_float(value, ty) {
    69→  return { "kind": "const_float", "value": value, "type": ty }
    70→}
    71→
    72→# bool 상수
    73→fn ir_val_bool(value) {
    74→  return { "kind": "const_bool", "value": value, "type": ir_type_bool() }
    75→}
    76→
    77→# null 포인터
    78→fn ir_val_null(ty) {
    79→  return { "kind": "const_null", "type": ty }
    80→}
    81→
    82→# 전역 심볼 참조 @name
    83→fn ir_val_global(name, ty) {
    84→  return { "kind": "global_ref", "name": name, "type": ty }
    85→}
    86→
    87→# ----------------------------------------------------------------
    88→# 3. Instruction 표현
    89→# ----------------------------------------------------------------
    90→
    91→# --- 산술/논리 ---
    92→
    93→fn ir_inst_binop(op, result_name, ty, lhs, rhs) {
    94→  # op: "add","sub","mul","div","rem","and","or","xor","shl","shr"
    95→  #     "fadd","fsub","fmul","fdiv"
    96→  return {
    97→    "kind": "binop",
    98→    "op": op,
    99→    "result": result_name,
   100→    "type": ty,
   101→    "lhs": lhs,
   102→    "rhs": rhs
   103→  }
   104→}
   105→
   106→fn ir_inst_neg(result_name, ty, operand) {
   107→  return { "kind": "neg", "result": result_name, "type": ty, "operand": operand }
   108→}
   109→
   110→# --- 비교 ---
   111→
   112→fn ir_inst_icmp(pred, result_name, ty, lhs, rhs) {
   113→  # pred: "eq","ne","lt","le","gt","ge","ult","ule","ugt","uge"
   114→  return {
   115→    "kind": "icmp",
   116→    "pred": pred,
   117→    "result": result_name,
   118→    "type": ty,
   119→    "lhs": lhs,
   120→    "rhs": rhs
   121→  }
   122→}
   123→
   124→fn ir_inst_fcmp(pred, result_name, ty, lhs, rhs) {
   125→  # pred: "oeq","one","olt","ole","ogt","oge"
   126→  return {
   127→    "kind": "fcmp",
   128→    "pred": pred,
   129→    "result": result_name,
   130→    "type": ty,
   131→    "lhs": lhs,
   132→    "rhs": rhs
   133→  }
   134→}
   135→
   136→# --- 메모리 ---
   137→
   138→fn ir_inst_alloca(result_name, ty) {
   139→  # entry block 전용
   140→  ptr_ty = ir_type_ptr(ty)
   141→  return { "kind": "alloca", "result": result_name, "alloc_type": ty, "type": ptr_ty }
   142→}
   143→
   144→fn ir_inst_load(result_name, ty, ptr_val) {
   145→  return { "kind": "load", "result": result_name, "type": ty, "ptr": ptr_val }
   146→}
   147→
   148→fn ir_inst_store(ty, val, ptr_val) {
   149→  return { "kind": "store", "type": ty, "val": val, "ptr": ptr_val }
   150→}
   151→
   152→fn ir_inst_gep(result_name, elem_ty, ptr_val, idx_val) {
   153→  ptr_ty = ir_type_ptr(elem_ty)
   154→  return {
   155→    "kind": "gep",
   156→    "result": result_name,
   157→    "elem_type": elem_ty,
   158→    "ptr": ptr_val,
   159→    "idx": idx_val,
   160→    "type": ptr_ty
   161→  }
   162→}
   163→
   164→# --- 타입 변환 ---
   165→
   166→fn ir_inst_cast(op, result_name, from_ty, val, to_ty) {
   167→  # op: "trunc","zext","sext","fpext","fptrunc","fptosi","sitofp","bitcast","ptrtoint","inttoptr"
   168→  return {
   169→    "kind": "cast",
   170→    "op": op,
   171→    "result": result_name,
   172→    "from_type": from_ty,
   173→    "val": val,
   174→    "to_type": to_ty,
   175→    "type": to_ty
   176→  }
   177→}
   178→
   179→# --- 함수 호출 ---
   180→
   181→fn ir_inst_call(result_name, ret_ty, callee, args) {
   182→  # result_name = "" 이면 void 호출
   183→  return {
   184→    "kind": "call",
   185→    "result": result_name,
   186→    "ret_type": ret_ty,
   187→    "callee": callee,
   188→    "args": args,
   189→    "type": ret_ty
   190→  }
   191→}
   192→
   193→# --- 제어 흐름 (Terminator) ---
   194→
   195→fn ir_inst_br(target_label) {
   196→  return { "kind": "br", "target": target_label }
   197→}
   198→
   199→fn ir_inst_br_cond(cond_val, true_label, false_label) {
   200→  return {
   201→    "kind": "br_cond",
   202→    "cond": cond_val,
   203→    "true_label": true_label,
   204→    "false_label": false_label
   205→  }
   206→}
   207→
   208→fn ir_inst_ret(val) {
   209→  return { "kind": "ret", "val": val }
   210→}
   211→
   212→fn ir_inst_ret_void() {
   213→  return { "kind": "ret_void" }
   214→}
   215→
   216→# --- Phi ---
   217→
   218→fn ir_inst_phi(result_name, ty, incoming) {
   219→  # incoming = [{ "val": IrVal, "block": string }, ...]
   220→  return {
   221→    "kind": "phi",
   222→    "result": result_name,
   223→    "type": ty,
   224→    "incoming": incoming
   225→  }
   226→}
   227→
   228→# ----------------------------------------------------------------
   229→# 4. Basic Block
   230→# ----------------------------------------------------------------
   231→
   232→fn ir_block(label, instructions) {
   233→  # instructions = [IrInst, ...]
   234→  # 마지막 inst는 terminator여야 함
   235→  return { "kind": "block", "label": label, "instructions": instructions }
   236→}
   237→
   238→fn ir_block_add_inst(block, inst) {
   239→  new_insts = append(block["instructions"], inst)
   240→  return { "kind": "block", "label": block["label"], "instructions": new_insts }
   241→}
   242→
   243→fn ir_block_is_terminated(block) {
   244→  insts = block["instructions"]
   245→  n = len(insts)
   246→  if n == 0 { return false }
   247→  last = insts[n - 1]
   248→  k = last["kind"]
   249→  return k == "br" or k == "br_cond" or k == "ret" or k == "ret_void"
   250→}
   251→
   252→# ----------------------------------------------------------------
   253→# 5. 함수 정의
   254→# ----------------------------------------------------------------
   255→
   256→fn ir_func(name, params, ret_ty, blocks, is_export) {
   257→  # params = [{ "name": string, "type": IrType }, ...]
   258→  # blocks = [IrBlock, ...]
   259→  return {
   260→    "kind": "function",
   261→    "name": name,
   262→    "params": params,
   263→    "ret_type": ret_ty,
   264→    "blocks": blocks,
   265→    "is_export": is_export
   266→  }
   267→}
   268→
   269→fn ir_func_extern(name, param_types, ret_ty, is_variadic) {
   270→  return {
   271→    "kind": "extern_fn",
   272→    "name": name,
   273→    "param_types": param_types,
   274→    "ret_type": ret_ty,
   275→    "is_variadic": is_variadic
   276→  }
   277→}
   278→
   279→# ----------------------------------------------------------------
   280→# 6. 전역 변수
   281→# ----------------------------------------------------------------
   282→
   283→fn ir_global(name, ty, init_val) {
   284→  return { "kind": "global", "name": name, "type": ty, "init": init_val }
   285→}
   286→
   287→# ----------------------------------------------------------------
   288→# 7. 모듈
   289→# ----------------------------------------------------------------
   290→
   291→fn ir_module(name) {
   292→  return {
   293→    "kind": "module",
   294→    "name": name,
   295→    "globals": [],
   296→    "externs": [],
   297→    "functions": []
   298→  }
   299→}
   300→
   301→fn ir_module_add_global(mod, global_def) {
   302→  new_globals = append(mod["globals"], global_def)
   303→  return {
   304→    "kind": "module",
   305→    "name": mod["name"],
   306→    "globals": new_globals,
   307→    "externs": mod["externs"],
   308→    "functions": mod["functions"]
   309→  }
   310→}
   311→
   312→fn ir_module_add_extern(mod, extern_def) {
   313→  new_externs = append(mod["externs"], extern_def)
   314→  return {
   315→    "kind": "module",
   316→    "name": mod["name"],
   317→    "globals": mod["globals"],
   318→    "externs": new_externs,
   319→    "functions": mod["functions"]
   320→  }
   321→}
   322→
   323→fn ir_module_add_function(mod, func_def) {
   324→  new_fns = append(mod["functions"], func_def)
   325→  return {
   326→    "kind": "module",
   327→    "name": mod["name"],
   328→    "globals": mod["globals"],
   329→    "externs": mod["externs"],
   330→    "functions": new_fns
   331→  }
   332→}
   333→
   334→# ----------------------------------------------------------------
   335→# 8. IR 텍스트 출력 (디버깅용)
   336→# ----------------------------------------------------------------
   337→
   338→fn ir_type_to_str(ty) {
   339→  k = ty["kind"]
   340→  if k == "primitive" { return ty["name"] }
   341→  if k == "ptr"       { return "ptr<" + ir_type_to_str(ty["inner"]) + ">" }
   342→  if k == "array"     { return "array<" + ir_type_to_str(ty["elem"]) + "," + str(ty["count"]) + ">" }
   343→  if k == "slice"     { return "slice<" + ir_type_to_str(ty["elem"]) + ">" }
   344→  if k == "struct"    { return "struct." + ty["name"] }
   345→  if k == "fn"        { return "fn_ptr" }
   346→  return "unknown_type"
   347→}
   348→
   349→fn ir_val_to_str(val) {
   350→  k = val["kind"]
   351→  if k == "reg"         { return "%" + val["name"] }
   352→  if k == "const_int"   { return str(val["value"]) }
   353→  if k == "const_float" { return str(val["value"]) }
   354→  if k == "const_bool"  {
   355→    if val["value"] { return "true" }
   356→    return "false"
   357→  }
   358→  if k == "const_null"  { return "null" }
   359→  if k == "global_ref"  { return "@" + val["name"] }
   360→  return "?"
   361→}
   362→
   363→fn ir_inst_to_str(inst) {
   364→  k = inst["kind"]
   365→
   366→  if k == "binop" {
   367→    return "%" + inst["result"] + " = " + inst["op"] + " " +
   368→           ir_type_to_str(inst["type"]) + " " +
   369→           ir_val_to_str(inst["lhs"]) + ", " + ir_val_to_str(inst["rhs"])
   370→  }
   371→
   372→  if k == "icmp" or k == "fcmp" {
   373→    return "%" + inst["result"] + " = " + k + " " + inst["pred"] + " " +
   374→           ir_type_to_str(inst["type"]) + " " +
   375→           ir_val_to_str(inst["lhs"]) + ", " + ir_val_to_str(inst["rhs"])
   376→  }
   377→
   378→  if k == "alloca" {
   379→    return "%" + inst["result"] + " = alloca " + ir_type_to_str(inst["alloc_type"])
   380→  }
   381→
   382→  if k == "load" {
   383→    return "%" + inst["result"] + " = load " +
   384→           ir_type_to_str(inst["type"]) + " " + ir_val_to_str(inst["ptr"])
   385→  }
   386→
   387→  if k == "store" {
   388→    return "store " + ir_type_to_str(inst["type"]) + " " +
   389→           ir_val_to_str(inst["val"]) + ", " + ir_val_to_str(inst["ptr"])
   390→  }
   391→
   392→  if k == "gep" {
   393→    return "%" + inst["result"] + " = gep " +
   394→           ir_type_to_str(inst["elem_type"]) + " " +
   395→           ir_val_to_str(inst["ptr"]) + ", " + ir_val_to_str(inst["idx"])
   396→  }
   397→
   398→  if k == "cast" {
   399→    return "%" + inst["result"] + " = " + inst["op"] + " " +
   400→           ir_type_to_str(inst["from_type"]) + " " +
   401→           ir_val_to_str(inst["val"]) + " to " + ir_type_to_str(inst["to_type"])
   402→  }
   403→
   404→  if k == "call" {
   405→    args_str = ""
   406→    i = 0
   407→    args = inst["args"]
   408→    while i < len(args) {
   409→      if i > 0 { args_str = args_str + ", " }
   410→      args_str = args_str + ir_val_to_str(args[i])
   411→      i = i + 1
   412→    }
   413→    if inst["result"] == "" {
   414→      return "call void " + ir_val_to_str(inst["callee"]) + "(" + args_str + ")"
   415→    }
   416→    return "%" + inst["result"] + " = call " +
   417→           ir_type_to_str(inst["ret_type"]) + " " +
   418→           ir_val_to_str(inst["callee"]) + "(" + args_str + ")"
   419→  }
   420→
   421→  if k == "br"       { return "br label %" + inst["target"] }
   422→  if k == "br_cond"  {
   423→    return "br bool " + ir_val_to_str(inst["cond"]) +
   424→           ", label %" + inst["true_label"] +
   425→           ", label %" + inst["false_label"]
   426→  }
   427→  if k == "ret"      { return "ret " + ir_val_to_str(inst["val"]) }
   428→  if k == "ret_void" { return "ret void" }
   429→
   430→  if k == "phi" {
   431→    incoming_str = ""
   432→    i = 0
   433→    ins = inst["incoming"]
   434→    while i < len(ins) {
   435→      if i > 0 { incoming_str = incoming_str + ", " }
   436→      incoming_str = incoming_str + "[" +
   437→        ir_val_to_str(ins[i]["val"]) + ", %" + ins[i]["block"] + "]"
   438→      i = i + 1
   439→    }
   440→    return "%" + inst["result"] + " = phi " +
   441→           ir_type_to_str(inst["type"]) + " " + incoming_str
   442→  }
   443→
   444→  return "# unknown_inst: " + k
   445→}
   446→
   447→fn ir_block_to_str(block) {
   448→  result = block["label"] + ":\n"
   449→  insts = block["instructions"]
   450→  i = 0
   451→  while i < len(insts) {
   452→    result = result + "  " + ir_inst_to_str(insts[i]) + "\n"
   453→    i = i + 1
   454→  }
   455→  return result
   456→}
   457→
   458→fn ir_func_to_str(func) {
   459→  k = func["kind"]
   460→
   461→  if k == "extern_fn" {
   462→    params_str = ""
   463→    i = 0
   464→    pts = func["param_types"]
   465→    while i < len(pts) {
   466→      if i > 0 { params_str = params_str + ", " }
   467→      params_str = params_str + ir_type_to_str(pts[i])
   468→      i = i + 1
   469→    }
   470→    if func["is_variadic"] { params_str = params_str + ", ..." }
   471→    return "extern fn @" + func["name"] + "(" + params_str + ") -> " +
   472→           ir_type_to_str(func["ret_type"])
   473→  }
   474→
   475→  prefix = "define fn "
   476→  if func["is_export"] { prefix = "export fn " }
   477→
   478→  params_str = ""
   479→  i = 0
   480→  params = func["params"]
   481→  while i < len(params) {
   482→    if i > 0 { params_str = params_str + ", " }
   483→    params_str = params_str + ir_type_to_str(params[i]["type"]) + " %" + params[i]["name"]
   484→    i = i + 1
   485→  }
   486→
   487→  header = prefix + "@" + func["name"] + "(" + params_str + ") -> " +
   488→           ir_type_to_str(func["ret_type"]) + " {\n"
   489→
   490→  body = ""
   491→  i = 0
   492→  blocks = func["blocks"]
   493→  while i < len(blocks) {
   494→    body = body + ir_block_to_str(blocks[i])
   495→    i = i + 1
   496→  }
   497→
   498→  return header + body + "}"
   499→}
   500→
   501→fn ir_module_to_str(mod) {
   502→  result = "module @" + mod["name"] + "\n\n"
   503→
   504→  # extern 선언
   505→  i = 0
   506→  exts = mod["externs"]
   507→  while i < len(exts) {
   508→    result = result + ir_func_to_str(exts[i]) + "\n"
   509→    i = i + 1
   510→  }
   511→
   512→  if len(exts) > 0 { result = result + "\n" }
   513→
   514→  # 전역 변수
   515→  i = 0
   516→  globs = mod["globals"]
   517→  while i < len(globs) {
   518→    g = globs[i]
   519→    result = result + "global @" + g["name"] + ": " +
   520→             ir_type_to_str(g["type"]) + "\n"
   521→    i = i + 1
   522→  }
   523→
   524→  if len(globs) > 0 { result = result + "\n" }
   525→
   526→  # 함수
   527→  i = 0
   528→  fns = mod["functions"]
   529→  while i < len(fns) {
   530→    result = result + ir_func_to_str(fns[i]) + "\n\n"
   531→    i = i + 1
   532→  }
   533→
   534→  return result
   535→}
