     1→# ================================================================
     2→# Free IR 1.0 — Reference Interpreter
     3→# IR → 실행 결과 (정확성 100% 목표, 속도 무관)
     4→#
     5→# 역할: IR의 의미 보존 증명
     6→# 이후: codegen 결과와 diff 비교로 self-verification
     7→# ================================================================
     8→
     9→# ----------------------------------------------------------------
    10→# 1. 실행 환경 (Environment)
    11→# ----------------------------------------------------------------
    12→
    13→# 인터프리터 상태
    14→fn interp_env(regs, memory, mem_ptr, call_stack, globals) {
    15→  # regs       : { reg_name → value }      SSA 레지스터 값
    16→  # memory     : [value, ...]               선형 메모리 (alloca/store/load)
    17→  # mem_ptr    : i64                        다음 할당 주소
    18→  # call_stack : [frame, ...]               호출 스택
    19→  # globals    : { name → value }           전역 심볼
    20→  return {
    21→    "regs":       regs,
    22→    "memory":     memory,
    23→    "mem_ptr":    mem_ptr,
    24→    "call_stack": call_stack,
    25→    "globals":    globals
    26→  }
    27→}
    28→
    29→fn interp_env_fresh(globals) {
    30→  return interp_env({}, [], 0, [], globals)
    31→}
    32→
    33→# 레지스터 읽기
    34→fn env_get_reg(env, name) {
    35→  v = env["regs"][name]
    36→  if v == null { return 0 }
    37→  return v
    38→}
    39→
    40→# 레지스터 쓰기
    41→fn env_set_reg(env, name, value) {
    42→  new_regs = map_set(env["regs"], name, value)
    43→  return {
    44→    "regs":       new_regs,
    45→    "memory":     env["memory"],
    46→    "mem_ptr":    env["mem_ptr"],
    47→    "call_stack": env["call_stack"],
    48→    "globals":    env["globals"]
    49→  }
    50→}
    51→
    52→# 메모리 alloca (주소 반환)
    53→fn env_alloca(env, size) {
    54→  addr = env["mem_ptr"]
    55→  new_ptr = addr + size
    56→  # 메모리 배열을 0으로 패딩 확장
    57→  new_mem = env["memory"]
    58→  i = len(new_mem)
    59→  while i < new_ptr {
    60→    new_mem = append(new_mem, 0)
    61→    i = i + 1
    62→  }
    63→  new_env = {
    64→    "regs":       env["regs"],
    65→    "memory":     new_mem,
    66→    "mem_ptr":    new_ptr,
    67→    "call_stack": env["call_stack"],
    68→    "globals":    env["globals"]
    69→  }
    70→  return { "addr": addr, "env": new_env }
    71→}
    72→
    73→# 메모리 load (주소 → 값)
    74→fn env_load(env, addr) {
    75→  mem = env["memory"]
    76→  if addr < 0 or addr >= len(mem) { return 0 }
    77→  return mem[addr]
    78→}
    79→
    80→# 메모리 store (주소 ← 값)
    81→fn env_store(env, addr, value) {
    82→  mem = env["memory"]
    83→  # 범위 확장
    84→  while len(mem) <= addr {
    85→    mem = append(mem, 0)
    86→  }
    87→  mem[addr] = value
    88→  return {
    89→    "regs":       env["regs"],
    90→    "memory":     mem,
    91→    "mem_ptr":    env["mem_ptr"],
    92→    "call_stack": env["call_stack"],
    93→    "globals":    env["globals"]
    94→  }
    95→}
    96→
    97→# ----------------------------------------------------------------
    98→# 2. 값(Value) 평가
    99→# ----------------------------------------------------------------
   100→
   101→fn interp_val(env, val) {
   102→  k = val["kind"]
   103→
   104→  if k == "const_int"   { return val["value"] }
   105→  if k == "const_float" { return val["value"] }
   106→  if k == "const_bool"  {
   107→    if val["value"] { return 1 }
   108→    return 0
   109→  }
   110→  if k == "const_null"  { return 0 }
   111→
   112→  if k == "reg" {
   113→    return env_get_reg(env, val["name"])
   114→  }
   115→
   116→  if k == "global_ref" {
   117→    g = env["globals"][val["name"]]
   118→    if g == null { return 0 }
   119→    return g
   120→  }
   121→
   122→  return 0
   123→}
   124→
   125→# ----------------------------------------------------------------
   126→# 3. Instruction 실행
   127→# ----------------------------------------------------------------
   128→
   129→# 실행 결과 타입
   130→fn interp_result_continue(env) {
   131→  return { "signal": "continue", "env": env }
   132→}
   133→
   134→fn interp_result_branch(label, env) {
   135→  return { "signal": "branch", "label": label, "env": env }
   136→}
   137→
   138→fn interp_result_return(value, env) {
   139→  return { "signal": "return", "value": value, "env": env }
   140→}
   141→
   142→fn interp_inst(env, inst) {
   143→  k = inst["kind"]
   144→
   145→  # --- 산술/논리 ---
   146→  if k == "binop" {
   147→    lv = interp_val(env, inst["lhs"])
   148→    rv = interp_val(env, inst["rhs"])
   149→    op = inst["op"]
   150→    result = 0
   151→
   152→    if op == "add"  { result = lv + rv }
   153→    if op == "sub"  { result = lv - rv }
   154→    if op == "mul"  { result = lv * rv }
   155→    if op == "div"  {
   156→      if rv == 0 { result = 0 }
   157→      else       { result = lv / rv }
   158→    }
   159→    if op == "rem"  {
   160→      if rv == 0 { result = 0 }
   161→      else       { result = lv % rv }
   162→    }
   163→    if op == "and"  { result = lv & rv }
   164→    if op == "or"   { result = lv | rv }
   165→    if op == "xor"  { result = lv ^ rv }
   166→    if op == "shl"  { result = lv << rv }
   167→    if op == "shr"  { result = lv >> rv }
   168→    if op == "fadd" { result = lv + rv }
   169→    if op == "fsub" { result = lv - rv }
   170→    if op == "fmul" { result = lv * rv }
   171→    if op == "fdiv" {
   172→      if rv == 0.0 { result = 0.0 }
   173→      else         { result = lv / rv }
   174→    }
   175→
   176→    env = env_set_reg(env, inst["result"], result)
   177→    return interp_result_continue(env)
   178→  }
   179→
   180→  if k == "neg" {
   181→    v = interp_val(env, inst["operand"])
   182→    env = env_set_reg(env, inst["result"], 0 - v)
   183→    return interp_result_continue(env)
   184→  }
   185→
   186→  # --- 비교 ---
   187→  if k == "icmp" or k == "fcmp" {
   188→    lv = interp_val(env, inst["lhs"])
   189→    rv = interp_val(env, inst["rhs"])
   190→    pred = inst["pred"]
   191→    cmp = 0
   192→
   193→    if pred == "eq"  or pred == "oeq" {
   194→      if lv == rv { cmp = 1 } else { cmp = 0 }
   195→    }
   196→    if pred == "ne"  or pred == "one" {
   197→      if lv != rv { cmp = 1 } else { cmp = 0 }
   198→    }
   199→    if pred == "lt"  or pred == "olt" or pred == "ult" {
   200→      if lv < rv  { cmp = 1 } else { cmp = 0 }
   201→    }
   202→    if pred == "le"  or pred == "ole" or pred == "ule" {
   203→      if lv <= rv { cmp = 1 } else { cmp = 0 }
   204→    }
   205→    if pred == "gt"  or pred == "ogt" or pred == "ugt" {
   206→      if lv > rv  { cmp = 1 } else { cmp = 0 }
   207→    }
   208→    if pred == "ge"  or pred == "oge" or pred == "uge" {
   209→      if lv >= rv { cmp = 1 } else { cmp = 0 }
   210→    }
   211→
   212→    env = env_set_reg(env, inst["result"], cmp)
   213→    return interp_result_continue(env)
   214→  }
   215→
   216→  # --- 메모리 ---
   217→  if k == "alloca" {
   218→    # alloca: 8바이트 공간 (i64 단위로 단순화)
   219→    r = env_alloca(env, 8)
   220→    env = env_set_reg(r["env"], inst["result"], r["addr"])
   221→    return interp_result_continue(env)
   222→  }
   223→
   224→  if k == "load" {
   225→    ptr = interp_val(env, inst["ptr"])
   226→    value = env_load(env, ptr)
   227→    env = env_set_reg(env, inst["result"], value)
   228→    return interp_result_continue(env)
   229→  }
   230→
   231→  if k == "store" {
   232→    ptr = interp_val(env, inst["ptr"])
   233→    value = interp_val(env, inst["val"])
   234→    env = env_store(env, ptr, value)
   235→    return interp_result_continue(env)
   236→  }
   237→
   238→  if k == "gep" {
   239→    base = interp_val(env, inst["ptr"])
   240→    idx  = interp_val(env, inst["idx"])
   241→    # 단순화: 1 unit = 8 bytes
   242→    addr = base + idx * 8
   243→    env = env_set_reg(env, inst["result"], addr)
   244→    return interp_result_continue(env)
   245→  }
   246→
   247→  # --- 타입 변환 (Phase 1: 값 보존 위주) ---
   248→  if k == "cast" {
   249→    v = interp_val(env, inst["val"])
   250→    op = inst["op"]
   251→    result = v
   252→    # 단순화: 인터프리터는 타입 구분 없이 값 보존
   253→    # trunc: 비트 마스크 적용
   254→    if op == "trunc" {
   255→      to_name = inst["to_type"]["name"]
   256→      if to_name == "i8"  or to_name == "u8"  { result = v & 0xFF }
   257→      if to_name == "i16" or to_name == "u16" { result = v & 0xFFFF }
   258→      if to_name == "i32" or to_name == "u32" { result = v & 0xFFFFFFFF }
   259→    }
   260→    if op == "zext" or op == "sext" or op == "fpext" or op == "fptrunc" { result = v }
   261→    if op == "fptosi" { result = int(v) }
   262→    if op == "sitofp" { result = float(v) }
   263→    if op == "bitcast" or op == "ptrtoint" or op == "inttoptr" { result = v }
   264→
   265→    env = env_set_reg(env, inst["result"], result)
   266→    return interp_result_continue(env)
   267→  }
   268→
   269→  # --- 함수 호출 ---
   270→  if k == "call" {
   271→    callee = inst["callee"]
   272→    args = inst["args"]
   273→    arg_vals = []
   274→    i = 0
   275→    while i < len(args) {
   276→      arg_vals = append(arg_vals, interp_val(env, args[i]))
   277→      i = i + 1
   278→    }
   279→
   280→    # 내장 함수 처리
   281→    callee_name = ""
   282→    if callee["kind"] == "global_ref" { callee_name = callee["name"] }
   283→
   284→    ret_val = interp_builtin(callee_name, arg_vals)
   285→
   286→    if inst["result"] != "" {
   287→      env = env_set_reg(env, inst["result"], ret_val)
   288→    }
   289→    return interp_result_continue(env)
   290→  }
   291→
   292→  # --- 제어 흐름 ---
   293→  if k == "br" {
   294→    return interp_result_branch(inst["target"], env)
   295→  }
   296→
   297→  if k == "br_cond" {
   298→    cond = interp_val(env, inst["cond"])
   299→    if cond != 0 {
   300→      return interp_result_branch(inst["true_label"], env)
   301→    }
   302→    return interp_result_branch(inst["false_label"], env)
   303→  }
   304→
   305→  if k == "ret" {
   306→    value = interp_val(env, inst["val"])
   307→    return interp_result_return(value, env)
   308→  }
   309→
   310→  if k == "ret_void" {
   311→    return interp_result_return(0, env)
   312→  }
   313→
   314→  # --- Phi ---
   315→  # phi는 블록 진입 시 별도 처리 (interp_block에서)
   316→  if k == "phi" {
   317→    # 이미 처리됨 — continue
   318→    return interp_result_continue(env)
   319→  }
   320→
   321→  return interp_result_continue(env)
   322→}
   323→
   324→# ----------------------------------------------------------------
   325→# 4. Basic Block 실행
   326→# ----------------------------------------------------------------
   327→
   328→fn interp_block(env, block, prev_label) {
   329→  insts = block["instructions"]
   330→  n = len(insts)
   331→
   332→  # phi 먼저 처리 (블록 첫 부분)
   333→  # phi incoming 값을 prev_label 기준으로 선택
   334→  i = 0
   335→  while i < n {
   336→    inst = insts[i]
   337→    if inst["kind"] == "phi" {
   338→      phi_val = interp_phi(env, inst, prev_label)
   339→      env = env_set_reg(env, inst["result"], phi_val)
   340→    }
   341→    i = i + 1
   342→  }
   343→
   344→  # 나머지 instruction 순차 실행
   345→  i = 0
   346→  while i < n {
   347→    inst = insts[i]
   348→    if inst["kind"] == "phi" {
   349→      i = i + 1
   350→      continue
   351→    }
   352→
   353→    r = interp_inst(env, inst)
   354→    env = r["env"]
   355→
   356→    if r["signal"] == "branch" {
   357→      return { "signal": "branch", "label": r["label"], "env": env }
   358→    }
   359→    if r["signal"] == "return" {
   360→      return { "signal": "return", "value": r["value"], "env": env }
   361→    }
   362→
   363→    i = i + 1
   364→  }
   365→
   366→  # terminator 없이 끝남 (잘못된 IR)
   367→  return { "signal": "return", "value": 0, "env": env }
   368→}
   369→
   370→fn interp_phi(env, phi_inst, prev_label) {
   371→  incoming = phi_inst["incoming"]
   372→  i = 0
   373→  while i < len(incoming) {
   374→    entry = incoming[i]
   375→    if entry["block"] == prev_label {
   376→      return interp_val(env, entry["val"])
   377→    }
   378→    i = i + 1
   379→  }
   380→  return 0
   381→}
   382→
   383→# ----------------------------------------------------------------
   384→# 5. 함수 실행
   385→# ----------------------------------------------------------------
   386→
   387→fn interp_function(func, arg_vals, globals) {
   388→  env = interp_env_fresh(globals)
   389→
   390→  # 파라미터 바인딩 (레지스터에 직접)
   391→  params = func["params"]
   392→  i = 0
   393→  while i < len(params) and i < len(arg_vals) {
   394→    p_name = params[i]["name"]
   395→    env = env_set_reg(env, p_name, arg_vals[i])
   396→    i = i + 1
   397→  }
   398→
   399→  # 블록 맵 구성 { label → block }
   400→  block_map = {}
   401→  blocks = func["blocks"]
   402→  i = 0
   403→  while i < len(blocks) {
   404→    b = blocks[i]
   405→    block_map = map_set(block_map, b["label"], b)
   406→    i = i + 1
   407→  }
   408→
   409→  # 실행 시작: entry 블록
   410→  current_label = "entry"
   411→  prev_label = ""
   412→  max_steps = 10000   # 무한 루프 방지
   413→
   414→  step = 0
   415→  while step < max_steps {
   416→    block = block_map[current_label]
   417→    if block == null {
   418→      return 0
   419→    }
   420→
   421→    r = interp_block(env, block, prev_label)
   422→    env = r["env"]
   423→
   424→    if r["signal"] == "return" {
   425→      return r["value"]
   426→    }
   427→
   428→    if r["signal"] == "branch" {
   429→      prev_label = current_label
   430→      current_label = r["label"]
   431→    }
   432→
   433→    step = step + 1
   434→  }
   435→
   436→  return 0
   437→}
   438→
   439→# ----------------------------------------------------------------
   440→# 6. 내장 함수 (builtin)
   441→# ----------------------------------------------------------------
   442→
   443→fn interp_builtin(name, args) {
   444→  # println / print
   445→  if name == "println" {
   446→    if len(args) > 0 {
   447→      println(args[0])
   448→    } else {
   449→      println("")
   450→    }
   451→    return 0
   452→  }
   453→
   454→  if name == "print" {
   455→    if len(args) > 0 {
   456→      print(args[0])
   457→    }
   458→    return 0
   459→  }
   460→
   461→  # 기본 수학 내장
   462→  if name == "abs" {
   463→    v = args[0]
   464→    if v < 0 { return 0 - v }
   465→    return v
   466→  }
   467→
   468→  if name == "max" {
   469→    if args[0] > args[1] { return args[0] }
   470→    return args[1]
   471→  }
   472→
   473→  if name == "min" {
   474→    if args[0] < args[1] { return args[0] }
   475→    return args[1]
   476→  }
   477→
   478→  # 함수를 찾지 못함 → 0
   479→  return 0
   480→}
   481→
   482→# ----------------------------------------------------------------
   483→# 7. 모듈 실행기 (진입점)
   484→# ----------------------------------------------------------------
   485→
   486→fn interp_module(ir_mod, entry_fn_name, args) {
   487→  # 전역 변수 초기화
   488→  globals = {}
   489→  globs = ir_mod["globals"]
   490→  i = 0
   491→  while i < len(globs) {
   492→    g = globs[i]
   493→    globals = map_set(globals, g["name"], g["init"])
   494→    i = i + 1
   495→  }
   496→
   497→  # 함수 맵 구성
   498→  func_map = {}
   499→  fns = ir_mod["functions"]
   500→  i = 0
   501→  while i < len(fns) {
   502→    f = fns[i]
   503→    func_map = map_set(func_map, f["name"], f)
   504→    i = i + 1
   505→  }
   506→
   507→  # 진입 함수 찾기
   508→  entry = func_map[entry_fn_name]
   509→  if entry == null {
   510→    println("ERROR: entry function not found: " + entry_fn_name)
   511→    return 0
   512→  }
   513→
   514→  return interp_function(entry, args, globals)
   515→}
