   518→# 유틸
   519→# ----------------------------------------------------------------
   520→
   521→fn map_get(m, key) {
   522→  if m == null { return null }
   523→  v = m[key]
   524→  if v == null { return null }
   525→  return v
   526→}
   527→
   528→fn map_set(m, key, value) {
   529→  if m == null { m = {} }
   530→  m[key] = value
   531→  return m
   532→}
